import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·26","description":"易小帖 - 卷四·26","frontmatter":{"title":"卷四·26","description":"易小帖 - 卷四·26"},"headers":[],"relativePath":"classics/yixiaotie/120.md","filePath":"classics/yixiaotie/120.md"}'),o={name:"classics/yixiaotie/120.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·26",tabindex:"-1"},[r("卷四·26 "),e("a",{class:"header-anchor",href:"#卷四·26","aria-label":"Permalink to “卷四·26”"},"​")],-1),e("p",null,"歸藏易卦名有異字，以坤為，以坎為犖，以震為釐，而他皆如字。家舊有歸藏鏡，八字皆異，相傳歸藏易本如是。要是後人偽為之者，今已無是物矣，但八異字下仍有八正字。予註易時，亡兒佩韋懸其鏡項間，指其字，無不認者。及能言，婢以骨牌與之，弄教以重六牌曰：此天牌也。曰：非也，此地牌耳。父嘗言坤為地，指鏡六畫曰：此非坤乎。婢以告予。予曰：童烏解玄。豈如是耶。後竟以痘殤，悲哉。按字書，有釐犖字，無字。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
